import { useEffect, useState } from "react";
import { Thermometer, FlaskConical, Milk, AlertTriangle } from "lucide-react";
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from "recharts";
import { LOTES_DEMO, TEMP_HIST, PH_HIST } from "../utils/constants";

const MetricCard = ({ label, value, icon:Icon, color }) => (
  <div style={{ background:"rgba(22,48,89,0.65)", border:"1px solid rgba(255,255,255,0.12)", borderRadius:12, padding:"18px 22px", display:"flex", alignItems:"center", gap:14 }}>
    <div style={{ background:`${color}22`, borderRadius:10, padding:10, display:"flex" }}>
      <Icon size={22} color={color}/>
    </div>
    <div>
      <div style={{ fontSize:11, color:"rgba(255,255,255,0.50)", fontWeight:600, textTransform:"uppercase", letterSpacing:"0.06em", marginBottom:3 }}>{label}</div>
      <div style={{ fontSize:26, fontWeight:800, letterSpacing:"-0.02em", lineHeight:1 }}>{value}</div>
    </div>
  </div>
);

const ChartCard = ({ title, data, dataKey, color, refY, refLabel, domain }) => (
  <div className="navy-card" style={{ padding:"22px" }}>
    <p style={{ fontFamily:"'Playfair Display',serif", fontWeight:700, fontSize:17, marginBottom:16 }}>{title}</p>
    <ResponsiveContainer width="100%" height={175}>
      <AreaChart data={data} margin={{top:5,right:5,left:-24,bottom:0}}>
        <defs>
          <linearGradient id={`g-${dataKey}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="15%" stopColor={color} stopOpacity={0.45}/>
            <stop offset="95%" stopColor={color} stopOpacity={0}/>
          </linearGradient>
        </defs>
        <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)"/>
        <XAxis dataKey="h" tick={{fontSize:9,fill:"rgba(255,255,255,0.35)"}} interval={3}/>
        <YAxis tick={{fontSize:9,fill:"rgba(255,255,255,0.35)"}} domain={domain||["auto","auto"]}/>
        <Tooltip contentStyle={{background:"#0d1e36",border:"1px solid rgba(255,255,255,0.15)",borderRadius:8,fontSize:12}}/>
        {refY && <ReferenceLine y={refY} stroke="#a8c8ec" strokeDasharray="4 4" label={{value:`Limit ${refLabel}`,fill:"#a8c8ec",fontSize:10}}/>}
        <Area type="monotone" dataKey={dataKey} stroke={color} strokeWidth={2} fill={`url(#g-${dataKey})`} dot={false}/>
      </AreaChart>
    </ResponsiveContainer>
  </div>
);

export default function Dashboard() {
  const [tempData] = useState(TEMP_HIST);
  const [phData]   = useState(PH_HIST);
  const COLS = "grid-cols-[1fr_1.3fr_0.8fr_0.7fr_0.6fr_0.9fr]";
  return (
    <div style={{ padding:"28px 32px", display:"flex", flexDirection:"column", gap:22 }} className="fade-up">
      {/* Métricas */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:14 }}>
        <MetricCard label="Temperature" value="6.8°C"   icon={Thermometer}  color="#6a9fd8"/>
        <MetricCard label="pH"          value="6.65"    icon={FlaskConical} color="#a8c8ec"/>
        <MetricCard label="Inventario"  value="1,250 L" icon={Milk}         color="#6a9fd8"/>
        <MetricCard label="Alertas"     value="2"       icon={AlertTriangle} color="#e74c3c"/>
      </div>
      {/* Gráficas */}
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:16 }}>
        <ChartCard title="Temperatura" data={tempData} dataKey="temp" color="#6a9fd8" refY={8} refLabel="8°C"/>
        <ChartCard title="Nivel de pH" data={phData}   dataKey="ph"  color="#a8c8ec" refY={6.8} refLabel="6.8" domain={[6.2,7.2]}/>
      </div>
      {/* Tabla registros */}
      <div className="navy-card" style={{ padding:"22px" }}>
        <p style={{ fontFamily:"'Playfair Display',serif", fontWeight:700, fontSize:17, marginBottom:16 }}>Registros Recientes</p>
        <div style={{ display:"grid", gridTemplateColumns:"1fr 0.8fr 1.2fr 0.9fr 0.8fr 0.9fr", padding:"10px 16px", borderBottom:"1px solid rgba(255,255,255,0.08)" }}>
          {["Fecha","Hora","Finca","Litros","pH","Estado"].map(h=>(
            <span key={h} style={{ fontSize:11, fontWeight:700, color:"rgba(255,255,255,0.40)", textTransform:"uppercase", letterSpacing:"0.06em" }}>{h}</span>
          ))}
        </div>
        {LOTES_DEMO.slice(0,5).map((l,i)=>(
          <div key={i} className="trow" style={{ gridTemplateColumns:"1fr 0.8fr 1.2fr 0.9fr 0.8fr 0.9fr" }}>
            <span style={{fontSize:13,color:"rgba(255,255,255,0.60)"}}>{l.fecha.split(" ")[0]}</span>
            <span style={{fontSize:13,color:"rgba(255,255,255,0.60)"}}>{l.fecha.split(" ")[1]}</span>
            <span style={{fontSize:13}}>{l.finca}</span>
            <span style={{fontSize:13}}>{l.litros.toLocaleString()}</span>
            <span style={{fontSize:13}}>{l.ph}</span>
            <span><span className={l.apta?"badge-apta":"badge-noapta"}>{l.apta?"APTA":"NO APTA"}</span></span>
          </div>
        ))}
      </div>
    </div>
  );
}
